#!/usr/bin/env node
// Decode the pinned Solana constants (docs/SOLANA.md) and the pinned validator (tools/validator.json)
// from base58 into C byte arrays, and the validator into app/src/validator.ts.
//
//   node tools/gen-consts.mjs           write core/include/tk_solana_consts.h, core/src/tk_solana_consts.c
//                                       and app/src/validator.ts
//   node tools/gen-consts.mjs --check   write nothing; exit 1 if the files are stale or SOLANA.md disagrees
//
// The generated files are committed, so building core/ never needs Node.
// No dependencies: Node 20+ only.

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

// Changing any value here changes which transactions the device signs: update docs/SOLANA.md in
// the same change (--check enforces that every value below appears there).
export const CONSTANTS = [
    { name: 'TK_SYSTEM_PROGRAM_ID', base58: '11111111111111111111111111111111', note: 'System Program' },
    { name: 'TK_TOKEN_PROGRAM_ID', base58: 'TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA', note: 'SPL Token Program (not Token-2022)' },
    { name: 'TK_ATA_PROGRAM_ID', base58: 'ATokenGPvbdGVxr1b2hvZbsiqW5xWH25efTNsLJA8knL', note: 'Associated Token Account Program' },
    { name: 'TK_DEVNET_USDC_MINT', base58: '4zMMC9srt5Ri5X14GAgXhaHii3GnPAEERYPJgZJDncDU', note: 'Devnet USDC mint (Circle)' },
    // Staking (Shapes C and D), checked against web3.js 1.98.4 and devnet 2026-11-19 (EXTRATASKS S0)
    { name: 'TK_STAKE_PROGRAM_ID', base58: 'Stake11111111111111111111111111111111111111', note: 'Stake Program' },
    { name: 'TK_STAKE_CONFIG_ID', base58: 'StakeConfig11111111111111111111111111111111', note: 'Stake config (DelegateStake still lists it)' },
    { name: 'TK_SYSVAR_RENT_ID', base58: 'SysvarRent111111111111111111111111111111111', note: 'Rent sysvar' },
    { name: 'TK_SYSVAR_CLOCK_ID', base58: 'SysvarC1ock11111111111111111111111111111111', note: 'Clock sysvar' },
    { name: 'TK_SYSVAR_STAKE_HISTORY_ID', base58: 'SysvarStakeHistory1111111111111111111111111', note: 'Stake history sysvar' },
];

export const STAKE_SPACE = 200; // bytes of a stake account (StakeStateV2)
export const STAKE_SEEDS = 16; // seeds tk-stake-0 .. tk-stake-15

// The one validator the device delegates to (tools/validator.json, chosen by the human).
export function loadValidator(path = join(dirname(fileURLToPath(import.meta.url)), 'validator.json')) {
    const v = JSON.parse(readFileSync(path, 'utf8'));
    if (typeof v.name !== 'string' || !/^[A-Za-z][A-Za-z0-9 ]{0,23}$/.test(v.name)) {
        throw new Error('validator.json: name must be 1-24 letters, digits or spaces, starting with a letter');
    }
    base58Decode(v.voteAccount); // throws unless it is 32 bytes
    if (v.say !== undefined && (typeof v.say !== 'string' || !/^[ -~]{1,40}$/.test(v.say))) {
        throw new Error('validator.json: say must be 1-40 printable ASCII characters');
    }
    // say: what text-to-speech is sent for the name clip, when the plain name comes out wrong.
    return { name: v.name, voteAccount: v.voteAccount, ...(v.say ? { say: v.say } : {}) };
}
export const USDC_DECIMALS = 6;
export const PUBKEY_LEN = 32;

const ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

// Base58 (Bitcoin/Solana alphabet) -> exactly `len` bytes. Throws on bad characters or wrong length.
export function base58Decode(s, len = PUBKEY_LEN) {
    if (typeof s !== 'string' || s.length === 0) {
        throw new Error('base58: empty input');
    }
    let n = 0n;
    for (const ch of s) {
        const v = ALPHABET.indexOf(ch);
        if (v < 0) {
            throw new Error(`base58: invalid character ${JSON.stringify(ch)} in ${s}`);
        }
        n = n * 58n + BigInt(v);
    }
    const body = [];
    while (n > 0n) {
        body.unshift(Number(n & 0xffn));
        n >>= 8n;
    }
    let zeros = 0;
    while (zeros < s.length && s[zeros] === '1') {
        zeros++;
    }
    const bytes = Uint8Array.from([...new Array(zeros).fill(0), ...body]);
    if (bytes.length !== len) {
        throw new Error(`base58: ${s} decodes to ${bytes.length} bytes, expected ${len}`);
    }
    return bytes;
}

const BANNER =
    '// GENERATED by tools/gen-consts.mjs from docs/SOLANA.md and tools/validator.json. Do not edit; rerun the script.\n';

/** The pinned constants plus the validator's vote account (TK_VALIDATOR_VOTE). */
export function allConstants(validator = loadValidator()) {
    return [
        ...CONSTANTS,
        {
            name: 'TK_VALIDATOR_VOTE',
            base58: validator.voteAccount,
            note: `Pinned validator vote account, "${validator.name}" (tools/validator.json)`,
        },
    ];
}

function cBytes(bytes) {
    const hex = [...bytes].map((b) => '0x' + b.toString(16).padStart(2, '0'));
    const lines = [];
    for (let i = 0; i < hex.length; i += 8) {
        lines.push('    ' + hex.slice(i, i + 8).join(', ') + ',');
    }
    return lines.join('\n');
}

// Returns { header, source } as strings. Deterministic: no timestamps, LF line endings.
export function generate(validator = loadValidator(), constants = allConstants(validator)) {
    const header = [
        BANNER,
        '#ifndef TK_SOLANA_CONSTS_H',
        '#define TK_SOLANA_CONSTS_H',
        '',
        '#include <stdint.h>',
        '',
        `#define TK_PUBKEY_LEN ${PUBKEY_LEN}u`,
        `#define TK_USDC_DECIMALS ${USDC_DECIMALS}u`,
        `#define TK_STAKE_SPACE ${STAKE_SPACE}u // bytes of a stake account`,
        `#define TK_STAKE_SEEDS ${STAKE_SEEDS}u  // stake account seeds tk-stake-0 .. tk-stake-${STAKE_SEEDS - 1}`,
        '',
        ...constants.flatMap((c) => [
            `// ${c.note}: ${c.base58}`,
            `extern const uint8_t ${c.name}[TK_PUBKEY_LEN];`,
        ]),
        '',
        '#endif',
        '',
    ].join('\n');

    const source = [
        BANNER,
        '#include "tk_solana_consts.h"',
        '',
        ...constants.flatMap((c) => [
            `// ${c.base58}`,
            `const uint8_t ${c.name}[TK_PUBKEY_LEN] = {`,
            cBytes(base58Decode(c.base58)),
            '};',
            '',
        ]),
    ].join('\n');

    const app = [
        BANNER,
        '// The pinned validator, for building stake transactions and naming it in speech. The device checks',
        '// the vote account itself (TK_VALIDATOR_VOTE in core/); this copy is only a convenience.',
        // name and voteAccount are validated by loadValidator (no quotes possible); Prettier style.
        'export const VALIDATOR = {',
        `    name: '${validator.name}',`,
        `    voteAccount: '${validator.voteAccount}',`,
        '} as const;',
        '',
    ].join('\n');

    return { header, source, app };
}

function main(argv) {
    const root = join(dirname(fileURLToPath(import.meta.url)), '..');
    const outputs = generate();
    const files = [
        [join(root, 'core', 'include', 'tk_solana_consts.h'), outputs.header],
        [join(root, 'core', 'src', 'tk_solana_consts.c'), outputs.source],
        [join(root, 'app', 'src', 'validator.ts'), outputs.app],
    ];

    if (!argv.includes('--check')) {
        for (const [path, text] of files) {
            writeFileSync(path, text);
            console.log(`wrote ${path}`);
        }
        return 0;
    }

    let ok = true;
    for (const [path, text] of files) {
        let current = null;
        try {
            current = readFileSync(path, 'utf8').replace(/\r\n/g, '\n');
        } catch {
            // missing file: reported below
        }
        if (current !== text) {
            console.error(`stale: ${path} (run node tools/gen-consts.mjs)`);
            ok = false;
        }
    }
    const solanaMd = readFileSync(join(root, 'docs', 'SOLANA.md'), 'utf8');
    for (const c of allConstants()) {
        if (!solanaMd.includes('`' + c.base58 + '`')) {
            console.error(`docs/SOLANA.md does not list ${c.name} = ${c.base58}`);
            ok = false;
        }
    }
    if (ok) {
        console.log('tk_solana_consts: up to date');
    }
    return ok ? 0 : 1;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
    process.exitCode = main(process.argv.slice(2));
}
